from pathlib import Path
from html import escape as e
import json
root=Path(__file__).parent; dist=root
projects=[p for p in json.loads((root/'projects.json').read_text()) if p.get('visible', True)]
def b(fr,en):return f'<span class="fr" lang="fr">{fr}</span><span class="en" lang="en">{en}</span>'
def logo():return '<img class="personal-logo" src="assets/logo.png" alt="">'
s='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Loïc Edoh — Portfolio</title><meta name="description" content="Portfolio de Loïc Edoh. Conception de jeux et de produits numériques : projets, contexte et contributions."><meta name="theme-color" content="#17181c"><meta property="og:title" content="Loïc Edoh — Portfolio"><meta property="og:description" content="Conception de jeux et de produits numériques. Projets et contributions."><link rel="icon" href="assets/logo.png"><link rel="stylesheet" href="styles/site.css"><link rel="stylesheet" href="styles/console.css?v=20261030-materials"><script src="scripts/site.js?v=20261030-materials" defer></script><script src="scripts/chassis.js?v=20261030-materials" defer></script></head><body>'''
s+=f'''<a class="skip" href="#screen">{b('Aller au contenu','Skip to content')}</a><main class="workspace"><div class="equipment"><section class="monitor" aria-label="Portfolio"><div class="bezel"><div class="screen" id="screen" tabindex="0" aria-label="Contenu de la cartouche / Cartridge content"><div class="screen-top"><span>LOIC EDOH</span><span class="screen-status" id="screen-role">Designer</span></div><div id="empty-screen" hidden><div class="slot-symbol" aria-hidden="true">↓</div><h1>{b('Insérez une cartouche','Insert a cartridge')}</h1><p>{b('Choisissez un projet ci-dessus.','Choose a project above.')}</p></div><article id="profile" class="project-panel profile-panel"><div class="profile-heading">{logo()}<div><p class="eyebrow">{b('Profil','Profile')}</p><h1>Loïc Edoh</h1><p class="roles">{b('Concepteur de jeux · Conception produit','Game Designer · Product Design')}</p></div></div><div class="profile-copy"><p>{b('Je conçois des systèmes et des expériences interactives, du jeu vidéo aux produits numériques. Mon travail couvre la recherche, la définition des mécaniques, le prototypage, la documentation et les itérations avec les équipes de production.','I design interactive systems and experiences, from video games to digital products. My work includes research, mechanics design, prototyping, documentation and iteration with production teams.')}</p><p>{b('J’ai travaillé sur Seekers of the Ancient chez Forge Hammer Entertainment. Je développe également Jam-In, une plateforme qui aide les gens à découvrir des événements de musique locaux.','I worked on Seekers of the Ancient at Forge Hammer Entertainment. I also develop Jam-In, a platform that helps people discover local music events.')}</p></div><div class="profile-section"><h2>{b('Projets','Projects')}</h2><div class="project-index">'''
for d in projects:s+=f'<a href="#{d["id"]}" class="index-link"><span>{e(d["title"])}</span><span aria-hidden="true">↗</span></a>'
s+=f'''</div></div><section class="profile-section contact"><h2>Contact</h2><a class="index-link" href="#contact-panel">{b("Formulaire de contact","Contact form")} <span aria-hidden="true">→</span></a><a href="mailto:l.edoh@outlook.com">l.edoh@outlook.com <span>↗</span></a><a href="https://www.linkedin.com/in/lo%C3%AFc-edoh-3798aa196/" target="_blank" rel="noopener noreferrer">LinkedIn <span>↗</span></a><a href="https://en-ra.itch.io/" target="_blank" rel="noopener noreferrer">itch.io <span>↗</span></a></section></article>'''
for d in projects:
 s+=f'<article id="{d["id"]}" class="project-panel" hidden><div class="project-heading"><p class="eyebrow">{b(*d["category"])}</p><h1>{e(d["title"])}</h1><p class="project-date">{b(*d["date"])}</p></div>'
 if d.get('video'):s+=f'<div class="lead-media"><video controls playsinline preload="none" poster="{d["image"]}" aria-label="{e(d["title"])}"><source src="{d["video"]}" type="video/mp4"></video></div>'
 elif d.get('youtube'):s+=f'<div class="lead-media youtube"><button class="video-poster" type="button" aria-label="Lire la vidéo / Play video"><img src="{d["image"]}" alt=""><span class="play-disc" aria-hidden="true">▶</span></button><iframe hidden data-src="https://www.youtube-nocookie.com/embed/{d["youtube"]}?rel=0" title="{e(d["title"])}" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen></iframe></div>'
 else:s+=f'<div class="lead-media still"><img src="{d["image"]}" alt="{e(d["title"])}" loading="lazy"></div>'
 if d.get('video_source'):s+=f'<a class="video-source" href="{d["video_source"]}" target="_blank" rel="noopener noreferrer">{b("Voir la vidéo source","View original video")} ↗</a>'
 s+=f'<div class="project-body"><p class="description">{b(*d["desc"])}</p><section class="contributions"><h2>Contributions</h2><ul>'+''.join('<li>'+b(*i)+'</li>' for i in d['items'])+'</ul></section>'
 if d.get('url'):s+=f'<a class="project-link" href="{d["url"]}" target="_blank" rel="noopener noreferrer">{b(*d["cta"])} <span aria-hidden="true">↗</span></a>'
 s+='</div>'
 gallery=[img for img in d.get('gallery',[]) if img and (dist/img).is_file()]
 if gallery:
  s+=f'<section class="project-gallery"><h2>{b("Images et documents","Images and documents")}</h2><div class="gallery-grid">'
  for j,img in enumerate(gallery):s+=f'<a href="{img}" target="_blank" rel="noopener"><img src="{img}" alt="{e(d["title"])} — {j+1}" loading="lazy"></a>'
  s+='</div></section>'
 s+=f'<section class="related-projects"><h2>{b("Autres projets","Other projects")}</h2><div class="related-grid">'
 position=projects.index(d)
 for offset in (1,2):
  other=projects[(position+offset)%len(projects)]
  s+=f'<a class="index-link related-link" href="#{other["id"]}"><img class="related-art" src="{other["image"]}" alt="" loading="lazy"><span>{e(other["title"])}</span><span aria-hidden="true">→</span></a>'
 s+='</div></section></article>' 
s+=f'''<article id="contact-panel" class="project-panel" hidden><div class="project-heading"><p class="eyebrow">{b('Écrivez-moi','Write to me')}</p><h1>Contact</h1></div><form id="contact-form" action="https://api.web3forms.com/submit" method="POST"><input type="hidden" name="access_key" value="ba5fc664-6fb5-4702-818b-b686d25e02b7"><input type="hidden" name="subject" value="Message depuis le portfolio de Loïc Edoh"><input type="checkbox" name="botcheck" hidden tabindex="-1"><label for="contact-name">{b('Nom','Name')}</label><input id="contact-name" name="name" autocomplete="name" maxlength="120" required><label for="contact-email">{b('Adresse courriel','Email address')}</label><input id="contact-email" type="email" name="email" autocomplete="email" maxlength="254" required><label for="contact-message">Message</label><textarea id="contact-message" name="message" rows="5" maxlength="10000" required></textarea><button class="project-link" type="submit">{b('Envoyer le message','Send message')} <span aria-hidden="true">↗</span></button><p id="contact-result" role="status" aria-live="polite"></p></form><p class="direct-email">{b('Ou par courriel :','Or by email:')} <a href="mailto:l.edoh@outlook.com">l.edoh@outlook.com</a></p></article>'''
s+=f'''</div></div><div class="control-deck"><div class="navigation-keys"><button id="profile-shortcut" class="hardware profile-key" type="button" aria-label="Profil / Profile">{logo()}{b('Profil','Profile')}</button><button id="contact-shortcut" class="hardware contact-key" type="button" aria-controls="contact-panel" aria-label="Contact"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></svg><span class="contact-caption">Contact</span></button><div class="speaker" aria-hidden="true"></div><div class="languages" role="group" aria-label="Langue / Language"><span class="language-slider" aria-hidden="true"></span><button type="button" data-lang="fr" aria-pressed="true" aria-label="Français">FR</button><button type="button" data-lang="en" aria-pressed="false" aria-label="English">EN</button></div></div><span class="power" aria-hidden="true"></span><button id="eject" class="eject-key" type="button" aria-label="Éjecter la cartouche / Eject cartridge"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 3 15h18L12 4Zm-9 14h18v3H3z"/></svg></button></div></section><div class="monitor-foot" aria-hidden="true"></div><section class="cartridge-module" aria-label="Cartouches / Cartridges"><div class="tray-cheek tray-cheek-left"><button id="shelf-prev" class="hardware shelf-arrow" aria-label="Cartouches précédentes / Previous cartridges" type="button">‹</button></div><div class="rack-window"><div class="cartridge-rack" id="cartridges">'''
entries=[{'id':'profile','title':'Profil','image':'assets/logo.png'}]+projects
for i,d in enumerate(entries):
 isprofile=d['id']=='profile'; isjam=d['id']=='jam-in'
 image='assets/featured/jam-in-logo.svg' if isjam else d['image']
 title=b('Profil','Profile') if isprofile else e('Lucky Luke' if d['id']=='lucky-luke' else d['title'])
 s+=f'''<div class="cartridge-slot"><a class="cartridge{' logo-cart' if isprofile or isjam else ''}{' jam-cart' if isjam else ''}" href="#{d['id']}" data-project="{d['id']}" aria-controls="{d['id']}" aria-expanded="false" aria-label="{e(d['title'])}"><span class="cart-ribs" aria-hidden="true"><img src="{image}" alt=""></span><span class="cart-label"><img src="{image}" alt="" loading="eager">{'<strong>'+title+'</strong>' if isprofile else ''}</span><span class="cart-base" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 8h14l-7 9z"/></svg></span></a><span class="selection-light" aria-hidden="true"></span></div>'''
s+=f'''</div><div class="module-lip" aria-hidden="true"></div></div><div class="tray-cheek tray-cheek-right"><button id="shelf-next" class="hardware shelf-arrow" aria-label="Cartouches suivantes / Next cartridges" type="button">›</button></div></section></div><footer><span id="loaded-name" role="status" aria-live="polite">{b('Profil','Profile')}</span><span class="rack-hint">{b('Choisissez une cartouche','Choose a cartridge')} <span aria-hidden="true">↓</span></span></footer></main><button id="back-to-top" type="button" aria-label="Haut de page / Scroll to top" hidden><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 14 6-6 6 6M12 8v12"/></svg></button></body></html>'''
# Put the cartridge reader before the screen in both visual and keyboard order.
module_start=s.index('<section class="cartridge-module"')
module_end=s.index('</section>',module_start)+len('</section>')
module=s[module_start:module_end]
s=s[:module_start]+s[module_end:]
s=s.replace('<div class="monitor-foot" aria-hidden="true"></div>','')
s=s.replace('<div class="equipment">','<div class="equipment">'+module+'<div class="monitor-foot" aria-hidden="true"></div>')
# Keep profile and language controls within reach directly below the reader.
controls_start=s.index('<div class="control-deck">')
controls_end=s.index('</div></section>',controls_start)+len('</div>')
controls=s[controls_start:controls_end]
s=s[:controls_start]+s[controls_end:]
s=s.replace('<div class="bezel">',controls+'<div class="bezel">',1)
assert 'github' not in s.lower() and 'profile_picture' not in s
(dist/'index.html').write_text(s)
